fun main() {
    var width = 100
    val chain = listOf("background:red", "padding:10", "background:blue", "padding:5")
    for (op in chain) {
        val (name, arg) = op.split(":")
        when (name) {
            "padding" -> width -= 2 * arg.toInt()
            "background" -> println("$arg fills $width")
        }
    }
    println("content $width")
}

